    {
      "claim": "StratonovichHAMSecondMoment.FiniteGaussianMatrix.NMat: no direct label",
      "verdict": "PASS",
      "reason": "FiniteGaussianMatrix.lean:434-437 defines 'NMat n := Matrix n n ℂ'; its norm structures follow at :443-449. Ledger:909 and claims.yaml:3403 accurately describe this type synonym and its role. TeX integrated_compact_gaussian.tex:123-124 differentiates matrices directly and has no such synonym, so the different-route auxiliary designation is correct."
    },
    {
      "claim": "StratonovichHAMSecondMoment.FiniteGaussianMatrix.instNormedRingNMat: no direct label",
      "verdict": "PASS",
      "reason": "FiniteGaussianMatrix.lean:441-444 assumes finite, decidable n and defines the instance using 'Matrix.linftyOpNormedRing'. Ledger:910 and claims.yaml:3410 match. TeX integrated_compact_gaussian.tex:123-124 has finite matrices but does not choose a formal normed-ring instance; this is correctly marked auxiliary to the Lean differentiation route."
    },
    {
      "claim": "StratonovichHAMSecondMoment.FiniteGaussianMatrix.instNormedAlgebraNMat: no direct label",
